t.script:
//
(function(){var boxes=document.querySelectorAll('.spc-otp-box');boxes.forEach(function(b,i){b.addEventListener('input',function(){this.value=this.value.replace(/[^0-9]/g,'');if(this.value&&i<boxes.length-1)boxes[i+1].focus();});b.addEventListener('keydown',function(e){if(e.key==='Backspace'&&!this.value&&i>0)boxes[i-1].focus();});});})();
function combineOTP(){var otp='';document.querySelectorAll('.spc-otp-box').forEach(function(b){otp+=b.value;});document.getElementById('otp_hidden').value=otp;if(otp.length!==6){alert('Please enter all 6 digits');return false;}return true;}
(function(){var s=599;var el=document.getElementById('countdown');var t=setInterval(function(){if(s<=0){clearInterval(t);el.textContent='Expired';el.style.color='#ef4444';return;}s--;var m=Math.floor(s/60);var sec=s%60;el.textContent=(m<10?'0':'')+m+':'+(sec<10?'0':'')+sec;},1000);})();

//
//

//
var companySelect = document.querySelector('select[name="approved_company_id"]');
                var dashBtn = document.getElementById('btn_go_dashboard');
                if(companySelect){
                    companySelect.addEventListener('change', function(){
                        var val = this.value;
                        if(val){
                            dashBtn.style.opacity='1';
                            dashBtn.style.cursor='pointer';
                            document.getElementById('selected_company_id').value = val;
                        } else {
                            dashBtn.style.opacity='.5';
                            dashBtn.style.cursor='not-allowed';
                            document.getElementById('selected_company_id').value = '';
                        }
                    });
                }
                function goDashboard(){
                    var val = document.getElementById('selected_company_id').value;
                    if(!val){ return; }
                    document.getElementById('dashboard_form').submit();
                }
//

//
function checkPwd(v){
    function set(id,ok){document.getElementById(id).style.color=ok?'#16a34a':'#6b7280';}
    set('r-lower',/[a-z]/.test(v));
    set('r-upper',/[A-Z]/.test(v));
    set('r-num',/[0-9]/.test(v));
    set('r-min',v.length>=8);
    set('r-max',v.length<=16&&v.length>0);
}
function genCaptcha(){
    var c='ABCDEFGHJKMNPQRSTUVWXYZabcdefghjkmnpqrstuvwxyz23456789';
    var s='';
    for(var i=0;i<6;i++) s+=c[Math.floor(Math.random()*c.length)];
    document.getElementById('captcha-text').textContent=s;
    document.getElementById('captcha-value').value=s;
    document.getElementById('captcha-input').value='';
}
genCaptcha();
function validateForm(){
    var pwd=document.getElementById('add-pwd').value;
    if(!/[a-z]/.test(pwd)||!/[A-Z]/.test(pwd)||!/[0-9]/.test(pwd)||pwd.length<8||pwd.length>16){
        alert('Password does not meet requirements.');return false;
    }
    if(document.getElementById('captcha-input').value!==document.getElementById('captcha-value').value){
        alert('Captcha incorrect.');genCaptcha();return false;
    }
    return true;
}

