div.script:
function toggleNotifDropdown() {
    var d = document.getElementById('notifDropdown');
    var p = document.getElementById('profileDropdown');
    p.style.display = 'none';
    var isOpen = d.style.display === 'block';
    d.style.display = isOpen ? 'none' : 'block';
    if (!isOpen) { fetchNotifications(); }
}
function fetchNotifications() {
    var list = document.getElementById('notifList');
    var badge = document.getElementById('notifBadge');
    list.innerHTML = '<div style="font-size:13px;color:#6b7280;text-align:center;padding:12px;">Loading...</div>';
    fetch('/spc/notifications', {
        method: 'POST',
        headers: {'Content-Type': 'application/json'},
        body: JSON.stringify({jsonrpc:'2.0', method:'call', params:{}})
    })
    .then(r => r.json())
    .then(data => {
        var result = data.result || {};
        var notifs = result.notifications || [];
        var count = result.unread_count || 0;
        if (count > 0) {
            badge.style.display = 'flex';
            badge.textContent = count > 9 ? '9+' : count;
        } else {
            badge.style.display = 'none';
        }
        if (notifs.length === 0) {
            list.innerHTML = '<div style="font-size:13px;color:#6b7280;text-align:center;padding:20px;">No notifications</div>';
        } else {
            list.innerHTML = notifs.map(function(n) {
                return '<div style="padding:10px 16px;border-bottom:1px solid #f3f4f6;' + (n.is_read ? '' : 'background:#f0f4ff;') + '">' +
                    '<div style="font-size:12px;color:#6b7280;margin-bottom:4px;">' + (n.company_name || '') + '</div>' +
                    '<div style="font-size:13px;color:#111827;">' + n.message + '</div>' +
                    '<div style="font-size:11px;color:#9ca3af;margin-top:4px;">' + (n.date || '') + '</div>' +
                '</div>';
            }).join('');
        }
    })
    .catch(function() {
        list.innerHTML = '<div style="font-size:13px;color:#ef4444;text-align:center;padding:12px;">Failed to load</div>';
    });
}
function toggleProfileDropdown() {
    var d = document.getElementById('profileDropdown');
    var n = document.getElementById('notifDropdown');
    n.style.display = 'none';
    d.style.display = d.style.display === 'none' ? 'block' : 'none';
}
document.addEventListener('click', function(e) {
    var nd = document.getElementById('notifDropdown');
    var pd = document.getElementById('profileDropdown');
    if (nd && !nd.parentElement.contains(e.target)) nd.style.display = 'none';
    if (pd && !pd.parentElement.contains(e.target)) pd.style.display = 'none';
});

