body.script:
//
(function(){
    var tabs = document.querySelectorAll('.service-tab');
    var sections = ['company-formation','establishment','business-license','corporate-letters','name-reservation','pre-approval','nma-media','nma-permit','employee-list'];
    tabs.forEach(function(tab){
        tab.addEventListener('click', function(e){
            e.preventDefault();
            var target = this.getAttribute('href').replace('#','');
            sections.forEach(function(k){
                var el = document.getElementById(k);
                if(el) el.style.display = 'none';
            });
            var el = document.getElementById(target);
            if(el) el.style.display = 'block';
            tabs.forEach(function(t){
                t.style.color = '#6b7280';
                t.style.borderLeft = 'none';
                t.style.fontWeight = 'normal';
            });
            this.style.color = '#1a3c6e';
            this.style.borderLeft = '3px solid #1a3c6e';
            this.style.fontWeight = '600';
        });
    });
})();
