var spcSelectedFiles = [];
                var spcBrowsedFiles = [];

                function openFileModal() {
                    var m = document.getElementById("spcFileModal");
                    m.style.display = "flex";
                    renderSpcFileGrid(spcBrowsedFiles, "");
                }
                function closeSpcModal(e) {
                    var m = document.getElementById("spcFileModal");
                    if (!e || e.target === m) m.style.display = "none";
                }
                function filterSpcFiles(q) { renderSpcFileGrid(spcBrowsedFiles, q); }
                function resetSpcDir() {
                    document.getElementById("spcBreadcrumbPath").textContent = "";
                    renderSpcFileGrid(spcBrowsedFiles, "");
                }
                function getFileIcon(name) {
                    var ext = name.split(".").pop().toLowerCase();
                    if (ext === "pdf") return "&#128196;";
                    if (["doc","docx"].includes(ext)) return "&#128196;";
                    if (["xls","xlsx"].includes(ext)) return "&#128202;";
                    if (["jpg","jpeg","png","gif"].includes(ext)) return "&#128247;";
                    if (["zip","rar"].includes(ext)) return "&#128230;";
                    return "&#128196;";
                }
                function renderSpcFileGrid(files, query) {
                    var grid = document.getElementById('spcFileGrid');
                    var filtered = files.filter(function(f) {
                        return !query || f.name.toLowerCase().includes(query.toLowerCase());
                    });
                    if (filtered.length === 0) {
                        grid.innerHTML = '<div style="grid-column:1/-1;text-align:center;color:#aaa;padding:40px">No files. Use BROWSE FILE to add.</div>';
                        return;
                    }
                    grid.innerHTML = filtered.map(function(f) {
                        var sel = spcSelectedFiles.includes(f.name) ? 'background:#e8f0fb;border:2px solid #1a3a5c' : 'border:2px solid transparent';
                        var item = document.createElement('div');
                        item.style.cssText = 'display:flex;flex-direction:column;align-items:center;padding:12px 8px;border-radius:6px;cursor:pointer;text-align:center;' + sel;
                        item.innerHTML = '<span style="font-size:28px">' + getFileIcon(f.name) + '</span><span style="font-size:11px;color:#444;word-break:break-all;margin-top:4px">' + f.name + '</span>';
                        item.onclick = function() { toggleSpcFile(f.name, item); };
                        return item.outerHTML;
                    }).join('');
                }
                function toggleSpcFile(name, el) {
                    var idx = spcSelectedFiles.indexOf(name);
                    if (idx > -1) {
                        spcSelectedFiles.splice(idx, 1);
                        el.style.background = "transparent";
                        el.style.borderColor = "transparent";
                    } else {
                        spcSelectedFiles.push(name);
                        el.style.background = "#e8f0fb";
                        el.style.borderColor = "#1a3a5c";
                    }
                }
                function handleSpcBrowse(input) {
                    Array.from(input.files).forEach(function(f) {
                        if (!spcBrowsedFiles.find(function(x){ return x.name === f.name; }))
                            spcBrowsedFiles.push(f);
                    });
                    document.getElementById("spcBreadcrumbPath").textContent = input.files.length ? " / " + input.files[0].name : "";
                    renderSpcFileGrid(spcBrowsedFiles, document.getElementById("spcFileSearch").value);
                }
                function confirmSpcSelection() {
                    if (spcSelectedFiles.length === 0) { alert("Please select at least one file."); return; }
                    var dt = new DataTransfer();
                    spcBrowsedFiles.forEach(function(f) {
                        if (spcSelectedFiles.includes(f.name)) dt.items.add(f);
                    });
                    document.getElementById("spcFileActual").files = dt.files;
                    document.getElementById("spcSelectedFileNames").textContent = "Selected: " + spcSelectedFiles.join(", ");
                    document.getElementById("spcFileModal").style.display = "none";
                }
//

//
window.addEventListener('load', function() {
    // Legal type change
    var legalRadios = document.querySelectorAll('input[name="legal_type"]');
    legalRadios.forEach(function(radio) {
        radio.addEventListener('change', function() {
            var brSection = document.getElementById('branch-section');
            var pkgNum = document.getElementById('package-step-num');
            if (this.value === 'branch') {
                brSection.style.display = 'block';
                if(pkgNum) pkgNum.textContent = '03';
            } else {
                brSection.style.display = 'none';
                if(pkgNum) pkgNum.textContent = '02';
                document.getElementById('inside-uae-fields').style.display = 'none';
                document.getElementById('board-resolution-section').style.display = 'none';
            }
        });
    });
    // Branch location change
    var branchLoc = document.getElementById('branch_location');
    if (branchLoc) {
        branchLoc.addEventListener('change', function() {
            var insideFields = document.getElementById('inside-uae-fields');
            var boardSection = document.getElementById('board-resolution-section');
            var extraFields = document.getElementById('inside-uae-extra-fields');
            if (this.value === 'inside_uae') {
                if(insideFields) insideFields.style.display = 'block';
                if(boardSection) boardSection.style.display = 'block';
                if(extraFields) extraFields.style.display = 'block';
            } else if (this.value === 'outside_uae') {
                if(insideFields) insideFields.style.display = 'none';
                if(boardSection) boardSection.style.display = 'block';
                if(extraFields) extraFields.style.display = 'none';
            } else {
                if(insideFields) insideFields.style.display = 'none';
                if(extraFields) extraFields.style.display = 'none';
            }
        });
    }
});

function validateAndNext() {
    // 1. Legal type check
    var legalType = document.querySelector('input[name="legal_type"]:checked');
    if (!legalType) {
        showSpcError('Please select a legal type to continue.');
        return;
    }

    // 2. Package type check
    var packageType = document.querySelector('input[name="package_type"]:checked');
    if (!packageType) {
        showSpcError('Please select a package type to continue.');
        return;
    }

    // 3. Branch validation
    if (legalType.value === 'branch') {
        var branchLoc = document.getElementById('branch_location');
        if (!branchLoc || !branchLoc.value) {
            showSpcError('Please select a branch location.');
            return;
        }
    }

    // All good - submit form
    document.querySelector('form').submit();
}

function showSpcError(msg) {
    // Remove existing error
    var existing = document.getElementById('spc-validation-error');
    if (existing) existing.remove();

    var err = document.createElement('div');
    err.id = 'spc-validation-error';
    err.style.cssText = 'position:fixed;top:24px;left:50%;transform:translateX(-50%);background:#fff;border:1.5px solid #e91e8c;border-radius:10px;padding:14px 28px;font-size:14px;color:#e91e8c;font-weight:600;box-shadow:0 8px 32px rgba(233,30,140,.15);z-index:99999;display:flex;align-items:center;gap:10px;animation:spcSlideIn .25s ease';
    err.innerHTML = '<span style="font-size:18px">⚠️</span><span>' + msg + '</span><button onclick="this.parentElement.remove()" style="background:none;border:none;color:#e91e8c;font-size:18px;cursor:pointer;margin-left:12px;line-height:1">×</button>';
    document.body.appendChild(err);

    // Auto remove after 4 seconds
    setTimeout(function() { if(err.parentElement) err.remove(); }, 4000);
}

// Add animation style
var spcStyle = document.createElement('style');
spcStyle.textContent = '@keyframes spcSlideIn{from{opacity:0;transform:translateX(-50%) translateY(-10px)}to{opacity:1;transform:translateX(-50%) translateY(0)}}';
document.head.appendChild(spcStyle);
