t.script:
var editing = false;
function toggleEdit() {
    editing = !editing;
    document.getElementById('viewMode').style.display = editing ? 'none' : 'grid';
    document.getElementById('editMode').style.display = editing ? 'grid' : 'none';
    document.getElementById('saveButtons').style.display = editing ? 'block' : 'none';
    var fields = ['building','area','street','zip','city','insta','fb','li','tw'];
    fields.forEach(function(f){
        var v = document.getElementById('v_'+f);
        var e = document.getElementById('e_'+f);
        if(v) v.style.display = editing ? 'none' : 'block';
        if(e) e.style.display = editing ? 'block' : 'none';
    });
}
